// Смешанные режимы замыкают неизменяемый список своей четверти.
for(const [g,topics] of Object.entries(TOP)){
 const year=[...topics];
 for(let q=1;q<=4;q++){const pool=year.filter(t=>t[3]===q);topics.push(['Все темы четверти',()=>pick(pool)[1](),'Повторение',q]);}
 topics.push(['Все темы года',()=>pick(year)[1](),'Повторение',0]);
}

// Разнообразные задачи внутри выбранной темы. Уровни: 1 — основа, 2 — применение, 3 — вызов.
const BANK={};
const FACT=n=>n<2?1:n*FACT(n-1),COMB=(n,k)=>FACT(n)/FACT(k)/FACT(n-k);
const pm=n=>n<0?'− '+nf(-n):'+ '+nf(n),poly=(a,b,c)=>`${a===1?'':a}x² ${pm(b)}x ${pm(c)}`;
const fracText=(n,d)=>frs(n,d),pair=(a,b)=>`(${nf(a)}; ${nf(b)})`;
function QN(text,value,wrong=[],note=''){const q=soloHintTrace(nq(text,value,[...wrong,value+1,value-1,value+2,value-2,-value],35),"task-204",[(typeof value==='number'?soloHintNumber(value):null)]);q.solution=note;q.numericAnswer=value;return q}
function QF(text,n,d,wrong=[],note=''){const q=soloHintTrace(fq(text,n,d,wrong,40),"task-205",[(typeof n==='number'?soloHintNumber(n):null),(typeof d==='number'?soloHintNumber(d):null)]);q.solution=note;q.numericAnswer=n/d;return q}
function QC(text,a,wrong,note=''){const q=soloHintTrace(mk(text,String(a),wrong.map(String),40,()=>['Не существует','Недостаточно данных','Любое действительное число','Ни одно из указанных'].filter(x=>x!==a)),"task-206",[null]);q.solution=note;return q}
function register(keys,fn){for(const key of keys.split(' '))BANK[key]=fn}
